import React, { useState } from "react";

const Chat = () => {
  const [userInput, setUserInput] = useState(""); // 사용자의 입력 상태
  const [chatHistory, setChatHistory] = useState([]); // 채팅 기록 상태

  // 메시지 전송 핸들러
  const handleSendMessage = async () => {
    if (userInput.trim() === "") return; // 빈 입력 방지

    // 사용자 메시지를 채팅 기록에 추가
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "user", message: userInput },
    ]);

    try {
      // 서버로 메시지 전송
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput }), // 입력 데이터를 JSON 형태로 전송
      });

      const data = await response.json(); // 서버 응답 받기

      // 서버 응답을 채팅 기록에 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: data.response },
      ]);
    } catch (error) {
      console.error("챗봇 응답 오류:", error);
    }

    setUserInput(""); // 입력 필드 초기화
  };

  return (
    <div>
      {/* 채팅 기록 표시 */}
      <div
        style={{
          height: "400px",
          overflowY: "scroll",
          border: "1px solid #ccc",
          padding: "10px",
          marginBottom: "10px",
        }}
      >
        {chatHistory.map((chat, index) => (
          <div
            key={index}
            style={{
              textAlign: chat.sender === "user" ? "right" : "left",
              margin: "5px 0",
            }}
          >
            <strong>{chat.sender === "user" ? "사용자:" : "챗봇:"}</strong>{" "}
            {chat.message}
          </div>
        ))}
      </div>

      {/* 메시지 입력 및 전송 버튼 */}
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)} // 입력 필드 업데이트
          placeholder="메시지를 입력하세요..."
          style={{ width: "300px", padding: "10px", marginRight: "10px" }}
        />
        <button onClick={handleSendMessage} style={{ padding: "10px 15px" }}>
          보내기
        </button>
      </div>
    </div>
  );
};

export default Chat;
